function OfflineSettingsWorkspace(props:{pendingCount:number;onPendingCount:(count:number)=>void}){
  return <><OfflineSettingsControls {...props}/><OfflineConflictReview/></>;
}
function OfflineSettingsControls({pendingCount,onPendingCount}:{pendingCount:number;onPendingCount:(count:number)=>void}){
  const [enabled,setEnabled]=useState(()=>offlineCaptureEnabled());const [notice,setNotice]=useState<string|null>(null);const [error,setError]=useState<string|null>(null);const [busy,setBusy]=useState(false);const [deviceId,setDeviceId]=useState<string|null>(null);const [queued,setQueued]=useState(0);const [conflicts,setConflicts]=useState(0);
  useEffect(()=>{void Promise.all([replicaDeviceId(),pendingSyncOperations(),syncConflicts()]).then(([id,operations,items])=>{setDeviceId(id);setQueued(operations.length);setConflicts(items.length);});},[]);
  async function change(value:boolean){setError(null);setNotice(null);if(!value){setEnabled(false);setOfflineCaptureEnabled(false);setNotice("New offline records will not be retained. Existing cached and pending records remain until erased.");return;}setBusy(true);try{let id=await replicaDeviceId();if(!id){const pairing=await api.createDevicePairing(`Trusted browser · ${navigator.platform||"web"}`);await api.approveDevicePairing(pairing.pairing_id,pairing.user_code,["sync:read","sync:write"]);const exchanged=await api.exchangeDevicePairing(pairing.pairing_id,pairing.device_code_once);id=exchanged.device_id;await setReplicaDeviceId(id);}setDeviceId(id);setOfflineCaptureEnabled(true);setEnabled(true);setNotice("This browser is enrolled for a private offline replica. Cached core records and pending writes remain local to this browser profile.");}catch(caught){setError(caught instanceof ApiError&&caught.code==="recent_strong_authentication_required"?"Sign out and sign in with your passkey, then enable the trusted browser within ten minutes.":"The trusted browser could not be enrolled; no offline replica was enabled.");}finally{setBusy(false);}}
  async function erase(){setError(null);try{const id=await replicaDeviceId();if(id)await api.revokeDevice(id);await Promise.all([clearPendingCaptures(),clearOfflineReplica()]);onPendingCount(0);setDeviceId(null);setQueued(0);setConflicts(0);setEnabled(false);setOfflineCaptureEnabled(false);setNotice("The local replica and pending records were erased, and its host device grant was revoked.");}catch{setError("The replica was not erased because its host device grant could not be revoked. Sign in again and retry.");}}
  return <><PageTitle eyebrow="Device trust" title="Settings" copy="Choose whether this browser may retain a private offline replica while the home host is unavailable."/><section className="settings-panel offline-settings"><label><input type="checkbox" checked={enabled} disabled={busy} onChange={event=>void change(event.target.checked)}/><span><strong>Trust this browser for offline use</strong><small>Explicitly enrolls this browser with sync-only scopes and stores cached core records plus pending captures/tasks/calendar writes in IndexedDB. Service-worker caches still exclude API responses.</small></span></label><div><span>{pendingCount} pending capture{pendingCount===1?"":"s"} · {queued} pending sync write{queued===1?"":"s"} · {conflicts} conflict{conflicts===1?"":"s"}</span><button className="text-button danger" disabled={busy||(!deviceId&&!pendingCount&&!queued&&!conflicts)} onClick={()=>void erase()}>Revoke and erase offline data</button></div>{deviceId&&<small>Replica device {deviceId.slice(0,8)} · cache is not remotely erasable while this browser is offline.</small>}{error&&<p className="form-error">{error}</p>}{notice&&<p className="success-banner">{notice}</p>}</section></>;
}

const sensitiveSchoolCategories:Preferences["sensitiveSchoolCategories"]=["attendance","performance","health","accommodations","discipline"];
function OwnerPreferencesWorkspace(){
  const [preferences,setPreferences]=useState<Preferences|null>(null);const [status,setStatus]=useState<SystemStatus|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState<string|null>(null);const [notice,setNotice]=useState<string|null>(null);
  async function refresh(){const [nextPreferences,nextStatus]=await Promise.all([api.preferences(),api.systemStatus()]);setPreferences(nextPreferences);setStatus(nextStatus);}
  useEffect(()=>{void refresh().catch(()=>setError("Owner preferences or host status could not be loaded."));},[]);
  function change<K extends keyof Preferences>(key:K,value:Preferences[K]){setPreferences(current=>current?{...current,[key]:value}:current);setNotice(null);}
  function toggleSensitive(category:Preferences["sensitiveSchoolCategories"][number],enabled:boolean){if(!preferences)return;change("sensitiveSchoolCategories",enabled?[...new Set([...preferences.sensitiveSchoolCategories,category])]:preferences.sensitiveSchoolCategories.filter(item=>item!==category));}
  async function save(event:FormEvent){event.preventDefault();if(!preferences)return;setBusy(true);setError(null);setNotice(null);try{const updated=await api.updatePreferences(preferences,{locale:preferences.locale,timezone:preferences.timezone,notificationChannels:preferences.notificationChannels,protectFocusTime:preferences.protectFocusTime,defaultFocusMinutes:preferences.defaultFocusMinutes,profileInferenceEnabled:preferences.profileInferenceEnabled,expandedDataEgressEnabled:preferences.expandedDataEgressEnabled,defaultPersonalDataSync:preferences.defaultPersonalDataSync,sensitiveSchoolCategories:preferences.sensitiveSchoolCategories});setPreferences(updated);setNotice("Owner policy saved with a new revision.");}catch(caught){setError(caught instanceof ApiError&&caught.status===409?"Preferences changed elsewhere. Reload Settings before retrying.":"Preferences were not saved.");}finally{setBusy(false);}}
  return <div className="settings-grid owner-preferences-grid"><section className="settings-panel"><div className="card-label"><Settings size={16}/> Owner policy</div><p className="panel-copy">These are explicit settings, never inferred preferences. They cannot contain commands, endpoints, credentials, or executable configuration.</p>{error&&<p className="form-error">{error}</p>}{notice&&<p className="success-banner">{notice}</p>}{preferences?<form className="rule-form" onSubmit={save}><label>Locale<input value={preferences.locale} onChange={event=>change("locale",event.target.value)} required/></label><label>Timezone<input value={preferences.timezone} onChange={event=>change("timezone",event.target.value)} required/></label><label>Default focus length<input type="number" min="15" max="240" value={preferences.defaultFocusMinutes} onChange={event=>change("defaultFocusMinutes",Number(event.target.value))}/></label><label>Default personal-data sync<select value={preferences.defaultPersonalDataSync} onChange={event=>change("defaultPersonalDataSync",event.target.value as Preferences["defaultPersonalDataSync"])}><option value="off">Off</option><option value="manual">Manual only</option><option value="scheduled">Scheduled when configured</option></select></label><div className="preference-checks"><label><input type="checkbox" checked={preferences.protectFocusTime} onChange={event=>change("protectFocusTime",event.target.checked)}/> Protect focus time by default</label><label><input type="checkbox" checked={preferences.notificationChannels.includes("windows_native")} onChange={event=>change("notificationChannels",event.target.checked?["in_app","windows_native"]:["in_app"])}/> Allow native Windows notifications when live-verified</label><label><input type="checkbox" checked={preferences.profileInferenceEnabled} onChange={event=>change("profileInferenceEnabled",event.target.checked)}/> Permit evidence-linked profile inference</label><label><input type="checkbox" checked={preferences.expandedDataEgressEnabled} onChange={event=>change("expandedDataEgressEnabled",event.target.checked)}/> Permit expanded provider data egress</label></div><fieldset><legend>Sensitive school categories</legend><div className="scope-grid">{sensitiveSchoolCategories.map(category=><label key={category}><input type="checkbox" checked={preferences.sensitiveSchoolCategories.includes(category)} onChange={event=>toggleSensitive(category,event.target.checked)}/>{category}</label>)}</div></fieldset><button className="primary" disabled={busy}>{busy?"Saving…":`Save policy · revision ${preferences.revision}`}</button></form>:<p className="quiet-empty">Loading owner policy…</p>}</section><section className="settings-panel"><div className="card-label"><Clock3 size={16}/> Host status</div><p className="panel-copy">Current host evidence only. Unconfigured services stay visibly unconfigured.</p>{status?<div className="status-evidence"><article><strong>Storage available</strong><small>{status.storage.vaultCount} vault{status.storage.vaultCount===1?"":"s"} · {(status.storage.databaseBytes/1_048_576).toFixed(1)} MB database</small></article><article><strong>{status.workers.online} of {status.workers.enrolled} workers online</strong><small>{status.workers.lastSeenAt?`Last seen ${friendlyDate(status.workers.lastSeenAt)}`:"No worker heartbeat recorded"}</small></article><article><strong>{status.sync.activeDevices} active sync device{status.sync.activeDevices===1?"":"s"}</strong><small>Event {status.sync.latestEventId} · retention floor {status.sync.retentionFloorEventId}</small></article><article><strong>Backup {status.backup.status.replaceAll("_"," ")}</strong><small>{status.backup.limitation}</small></article><article><strong>API {status.versions.api} · schema {status.versions.schema}</strong><small>Checked {friendlyDate(status.checkedAt)}</small></article></div>:<p className="quiet-empty">Loading host evidence…</p>}</section></div>;
}

const grantableDeviceScopes:DeviceScope[]=["vault:read","export:read","sync:read","sync:write","capture:write","notes:write","tasks:write","calendar:write","school:write","study:write","profile:write","integrations:write","ai:run","jobs:write"];
function DeviceAccessWorkspace(){
  const [devices,setDevices]=useState<DeviceSummary[]>([]);const [tokens,setTokens]=useState<ApiTokenSummary[]>([]);const [pairingId,setPairingId]=useState("");const [userCode,setUserCode]=useState("");const [label,setLabel]=useState("");const [scopes,setScopes]=useState<DeviceScope[]>(["vault:read","capture:write"]);const [secret,setSecret]=useState<string|null>(null);const [notice,setNotice]=useState<string|null>(null);const [error,setError]=useState<string|null>(null);const [nativeChallenge,setNativeChallenge]=useState<NativePairingChallenge|null>(null);const [nativeStatus,setNativeStatus]=useState<NativeAuthStatus|null>(null);
  async function refresh(){const [nextDevices,nextTokens]=await Promise.all([api.devices(),api.apiTokens()]);setDevices(nextDevices.items);setTokens(nextTokens.items);}
  useEffect(()=>{void refresh().catch(()=>setError("Authorized devices and tokens could not be loaded."));if(desktopBridge)void desktopBridge.authStatus().then(setNativeStatus).catch(()=>setError("Windows Credential Manager status is unavailable."));},[]);
  function toggle(scope:DeviceScope,enabled:boolean){setScopes(current=>enabled?[...new Set([...current,scope])]:current.filter(item=>item!==scope));setSecret(null);}
  async function beginNativePairing(){if(!desktopBridge)return;setError(null);setNotice(null);try{const challenge=await desktopBridge.beginPairing("Sorta Windows desktop");setNativeChallenge(challenge);setPairingId(challenge.pairingId);setUserCode(challenge.userCode);setNotice("The native client created a one-time request. Review the scopes and approve it below before the code expires.");}catch{setError("The native client could not start pairing with the configured host.");}}
  async function finishNativePairing(){if(!desktopBridge)return;try{const result=await desktopBridge.pollPairing();if(result.status==="pending"){setNotice(`The host has not approved this request yet. Retry in ${result.retryAfterSeconds} seconds.`);return;}setNativeChallenge(null);setNativeStatus(await desktopBridge.authStatus());setNotice("Windows client paired. Its rotating refresh credential is protected by Windows Credential Manager; the renderer never receives it.");await refresh();}catch{setError("The one-time exchange failed or expired. Start a new native pairing request.");}}
  async function approve(event:FormEvent){event.preventDefault();setError(null);setNotice(null);try{const approvedId=pairingId.trim();await api.approveDevicePairing(approvedId,userCode.trim(),scopes);setPairingId("");setUserCode("");if(desktopBridge&&nativeChallenge?.pairingId===approvedId){await finishNativePairing();}else{setNotice("Device approved for exactly the selected vault and scopes. It still must complete its one-time exchange.");}}catch(caught){setError(caught instanceof ApiError&&caught.code==="recent_strong_authentication_required"?"Sign out and sign in with your passkey, then approve the device within ten minutes.":"Pairing approval failed. Check both codes, expiry, role, and selected scopes.");}}
  async function createToken(event:FormEvent){event.preventDefault();setError(null);setNotice(null);setSecret(null);try{const created=await api.createApiToken(label.trim(),scopes);setSecret(created.secret_once);setLabel("");setNotice("Token created for 30 days. Copy it now; only its hash is stored.");await refresh();}catch(caught){setError(caught instanceof ApiError&&caught.code==="recent_strong_authentication_required"?"Sign out and sign in with your passkey, then create the token within ten minutes.":"The token was not created.");}}
  async function revokeDevice(device:DeviceSummary){setError(null);try{await api.revokeDevice(device.id);await refresh();}catch{setError("The device was not revoked. Recent passkey authentication may be required.");}}
  async function revokeToken(token:ApiTokenSummary){setError(null);try{await api.revokeApiToken(token.id);await refresh();}catch{setError("The API token was not revoked.");}}
  async function revokeThisNativeClient(){if(!desktopBridge)return;setError(null);try{if(nativeStatus?.deviceId)await api.revokeDevice(nativeStatus.deviceId);await desktopBridge.unpair();setNativeStatus(await desktopBridge.authStatus());setNativeChallenge(null);setNotice("This Windows client was revoked on the host and its local credential was removed.");await refresh();}catch{setError("The native client could not be fully revoked. Check the host device list before forgetting local access.");}}
  return <section className="settings-panel settings-wide"><div className="card-label"><KeyRound size={16}/> Devices and scoped API access</div><p className="panel-copy">Pairing secrets and API tokens are shown once, stored hashed on the host, bound to this vault, and never grant shell, SQL, filesystem, or arbitrary network access. Refresh-token replay revokes the entire device.</p>{error&&<p className="form-error">{error}</p>}{notice&&<p className="success-banner">{notice}</p>}{desktopBridge&&<div className="native-device-card"><div><strong>This Windows client</strong><small>{nativeStatus?.paired?`Paired · ${nativeStatus.scopes.join(", ")} · refresh expires ${friendlyDate(nativeStatus.refreshExpiresAt!)}`:nativeChallenge?`Waiting for approval · code ${nativeChallenge.userCode}`:"Not paired for native background requests"}</small></div><div className="session-actions">{!nativeStatus?.paired&&!nativeChallenge&&<button className="text-button" onClick={()=>void beginNativePairing()}>Start native pairing</button>}{nativeChallenge&&<button className="text-button" onClick={()=>void finishNativePairing()}>Check approval</button>}{nativeStatus?.paired&&<button className="text-button danger" onClick={()=>void revokeThisNativeClient()}>Revoke this client</button>}</div></div>}<fieldset><legend>Allowed scopes</legend><div className="scope-grid">{grantableDeviceScopes.map(scope=><label key={scope}><input type="checkbox" checked={scopes.includes(scope)} onChange={event=>toggle(scope,event.target.checked)}/><span>{scope}</span></label>)}</div></fieldset><div className="device-access-forms"><form className="rule-form" onSubmit={approve}><strong>Approve one-time pairing</strong><input value={pairingId} onChange={event=>setPairingId(event.target.value)} placeholder="Pairing UUID" required/><input value={userCode} onChange={event=>setUserCode(event.target.value)} placeholder="ABCD-EFGH" required/><button className="primary" disabled={!pairingId.trim()||!userCode.trim()||!scopes.length}>Approve client</button></form><form className="rule-form" onSubmit={createToken}><strong>Create API token</strong><input value={label} onChange={event=>setLabel(event.target.value)} placeholder="CLI or integration label" required/><button className="primary" disabled={!label.trim()||!scopes.length}>Create 30-day token</button>{secret&&<div className="one-time-secret"><b>Copy once</b><code>{secret}</code></div>}</form></div><div className="settings-list">{devices.map(device=><article key={device.id}><div><strong>{device.name} · {device.role}</strong><small>{device.scopes.join(", ")} · {device.last_seen_at?`last used ${friendlyDate(device.last_seen_at)}`:"never used"}</small></div><button className="text-button danger" onClick={()=>void revokeDevice(device)}>Revoke device</button></article>)}{tokens.map(token=><article key={token.id}><div><strong>{token.label} · API token</strong><small>{token.scopes.join(", ")} · expires {friendlyDate(token.expires_at)} · {token.last_used_at?`last used ${friendlyDate(token.last_used_at)}`:"never used"}</small></div><button className="text-button danger" onClick={()=>void revokeToken(token)}>Revoke token</button></article>)}{!devices.length&&!tokens.length&&<p className="quiet-empty">No paired devices or active API tokens.</p>}</div></section>;
}

function VaultExportWorkspace(){const [format,setFormat]=useState<"markdown_bundle"|"full_fidelity">("full_fidelity");const [includeHistory,setIncludeHistory]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState<string|null>(null);const [download,setDownload]=useState<{url:string;expiresAt:string;byteLength:number;sha256:string}|null>(null);async function generate(){setBusy(true);setError(null);setDownload(null);try{const handle=await api.createVaultExport(format,includeHistory),job=await api.job(handle.id);if(job.result?.type!=="export_generate")throw new Error("export_not_ready");const manifest=await api.exportManifest(job.result.exportId);if(manifest.status!=="ready"||manifest.byteLength===null||!manifest.sha256)throw new Error("export_not_ready");setDownload({url:api.exportDownloadUrl(manifest.id),expiresAt:manifest.expiresAt,byteLength:manifest.byteLength,sha256:manifest.sha256});}catch{setError("The authorized vault snapshot could not be generated.");}finally{setBusy(false);}}return <section className="settings-panel"><div className="card-label"><Archive size={16}/> Private vault export</div><p className="panel-copy">Create a consistent owner-authorized archive of the selected vault domains. The bundle contains a manifest and original source files, remains private, and expires after 24 hours.</p><div className="assignment-form"><select value={format} onChange={event=>{setFormat(event.target.value as typeof format);setDownload(null);}}><option value="full_fidelity">Full fidelity</option><option value="markdown_bundle">Markdown bundle</option></select><label className="repeat-toggle"><input type="checkbox" checked={includeHistory} onChange={event=>{setIncludeHistory(event.target.checked);setDownload(null);}}/> Include revision history</label><button className="primary" disabled={busy} onClick={()=>void generate()}>{busy?"Building snapshot…":"Create private export"}</button></div>{error&&<p className="form-error">{error}</p>}{download&&<div className="rule-preview"><strong>Artifact ready · {Math.max(1,Math.ceil(download.byteLength/1024))} KB</strong><span>SHA-256 {download.sha256}</span><small>Expires {friendlyDate(download.expiresAt)}. Authorization, expiry, and checksum are checked again on download.</small><a className="text-button" href={download.url} download>Download archive</a></div>}</section>;}

function SettingsWorkspace() {
  const [rules, setRules] = useState<RoutingRule[]>([]);
  const [labels, setLabels] = useState<Label[]>([]);
  const [operations, setOperations] = useState<AiOperation[]>([]);
  const [activity, setActivity] = useState<ActivityEvent[]>([]);
  const [name, setName] = useState("");
  const [classification, setClassification] = useState<NonNullable<Note["classification"]>>("task");
  const [labelId, setLabelId] = useState("");
  const [preview, setPreview] = useState<RulePreviewResult | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  async function refresh() {
    const [nextRules, nextLabels, nextOperations, nextActivity] = await Promise.all([api.rules(), api.labels(), api.aiOperations(), api.activity()]);
    setRules(nextRules.items); setLabels(nextLabels.items); setOperations(nextOperations.items); setActivity(nextActivity.items);
    setLabelId(current => current || nextLabels.items[0]?.id || "");
  }
  useEffect(() => { void refresh().catch(() => setError("Could not load organization controls.")); }, []);
  function invalidatePreview() { setPreview(null); setNotice(null); }
  async function previewRule() {
    if (!labelId) return; setBusy(true); setError(null);
    try { setPreview(await api.previewRule(classification, labelId)); }
    catch { setError("The rule preview could not be calculated. Nothing was changed."); }
    finally { setBusy(false); }
  }
  async function createRule(event: FormEvent) {
    event.preventDefault(); if (!name.trim() || !labelId || !preview) return; setBusy(true); setError(null);
    try { await api.createRule(name.trim(), classification, labelId); setName(""); setPreview(null); setNotice("Rule created. It applies only to future successful classification results."); await refresh(); }
    catch { setError("The rule was not created."); }
    finally { setBusy(false); }
  }
  async function toggleRule(rule: RoutingRule) {
    setError(null); try { await api.setRuleEnabled(rule, !rule.enabled); await refresh(); } catch { setError("The rule changed elsewhere. Reload and try again."); }
  }
  async function removeRule(rule: RoutingRule) {
    setError(null); try { await api.deleteRule(rule); await refresh(); } catch { setError("The rule could not be removed. Historical labels were not changed."); }
  }
  async function undo(operation: AiOperation) {
    if (!operation.noteId) return; setError(null); setNotice(null);
    try { const note = await api.note(operation.noteId); const receipt = await api.undoAiOperation(operation.id, note.revision); setNotice(`Restored the prior classification and removed ${receipt.removedRuleLabels} rule label${receipt.removedRuleLabels === 1 ? "" : "s"}.`); await refresh(); }
    catch (caught) { setError(caught instanceof ApiError && caught.status === 409 ? "Undo was blocked because the note changed after this operation." : "Undo could not be completed."); }
  }

  return <><PageTitle eyebrow="Owner controls" title="Settings" copy="Preview automation before enabling it, inspect model-authored changes, and undo only while the recorded effect is still current."/>
    {error && <p className="form-error">{error}</p>}{notice && <p className="success-banner">{notice}</p>}
    <div className="settings-grid"><section className="settings-panel"><div className="card-label"><Settings size={16}/> Routing rules</div>
      <form className="rule-form" onSubmit={createRule}><label>Rule name<input value={name} onChange={event => setName(event.target.value)} placeholder="File tasks into Action" required/></label><label>When classification is<select value={classification} onChange={event => { setClassification(event.target.value as typeof classification); invalidatePreview(); }}>{["note", "task", "event", "idea", "reference", "unknown"].map(value => <option key={value}>{value}</option>)}</select></label><label>Add label<select value={labelId} onChange={event => { setLabelId(event.target.value); invalidatePreview(); }} disabled={!labels.length}><option value="">Choose a label</option>{labels.map(label => <option key={label.id} value={label.id}>{label.name}</option>)}</select></label><div className="rule-actions"><button type="button" className="text-button" disabled={busy || !labelId} onClick={() => void previewRule()}>Preview effects</button><button className="primary" disabled={busy || !name.trim() || !preview}>Create enabled rule</button></div></form>
      {preview && <div className="rule-preview"><strong>{preview.affectedCount} existing note{preview.affectedCount === 1 ? "" : "s"} match</strong><span>Preview only—existing notes will not be changed. The rule applies to future classifications.</span>{preview.conflicts.length > 0 && <small>{preview.conflicts.length} conflict{preview.conflicts.length === 1 ? "" : "s"} need review.</small>}</div>}
      <div className="settings-list">{rules.map(rule => <article key={rule.id}><div><strong>{rule.name}</strong><small>Priority {rule.priority} · revision {rule.revision} · {rule.targetLabelIds.length} destination{rule.targetLabelIds.length === 1 ? "" : "s"}</small></div><button className="text-button" onClick={() => void toggleRule(rule)}>{rule.enabled ? "Disable" : "Enable"}</button><button className="text-button danger" onClick={() => void removeRule(rule)}>Remove</button></article>)}{rules.length === 0 && <p className="quiet-empty">No routing rules. Manual labels stay in control.</p>}</div>
    </section><section className="settings-panel"><div className="card-label"><Sparkles size={16}/> AI change history</div><div className="settings-list">{operations.map(operation => <article key={operation.id}><div><strong>Classification · revision {operation.sourceRevision}</strong><small>{new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(operation.createdAt))} · model {operation.modelDigest ? operation.modelDigest.slice(0, 12) : "digest unavailable"}</small><small>{operation.undoneAt ? "Undone" : operation.applied ? "Applied" : "Recorded, not applied"}</small></div>{operation.applied && !operation.undoneAt && <button className="text-button" onClick={() => void undo(operation)}>Undo</button>}</article>)}{operations.length === 0 && <p className="quiet-empty">No model-authored changes have been recorded.</p>}</div></section>
    <section className="settings-panel settings-wide"><div className="card-label"><Clock3 size={16}/> Recent activity</div><div className="settings-list activity-list">{activity.map(item => <article key={item.id}><div><strong>{item.summary}</strong><small>{new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(new Date(item.createdAt))} · {item.actor} · {item.objectType.replace("_", " ")}</small></div></article>)}{activity.length === 0 && <p className="quiet-empty">No durable activity has been recorded yet.</p>}</div></section></div>
  </>;
}

function TaskRow({ task, onToggle }: { task: Task; onToggle: () => void }) { return <button className={task.completed ? "task-row done" : "task-row"} onClick={onToggle}>{task.completed ? <CheckCircle2 size={20}/> : <Circle size={20}/>}<span>{task.title}</span>{task.dueAt && <time>{friendlyDate(task.dueAt)}</time>}</button>; }

function NoteList({ notes, onOpen }: { notes: Note[]; onOpen?: (note: Note) => void }) { return <div className="notes-grid">{notes.map(note => <article className={onOpen ? "note-card interactive" : "note-card"} key={note.id} onClick={() => onOpen?.(note)} onKeyDown={event => { if (onOpen && (event.key === "Enter" || event.key === " ")) onOpen(note); }} tabIndex={onOpen ? 0 : undefined}><div className="note-meta"><Archive size={15}/><span>{note.classification ?? "unclassified"}{note.classificationLocked ? " · locked" : ""}</span><time>{new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric" }).format(new Date(note.updatedAt))}</time></div><h3>{note.title}</h3><p>{note.body}</p><small>Revision {note.revision} · {note.status}</small></article>)}{notes.length === 0 && <div className="large-empty"><Brain/><h2>Your brain is ready</h2><p>Capture your first note. It will remain available even if AI is offline.</p></div>}</div>; }

function NoteEditor({ note, onClose, onSaved,onTrashed }: { note: Note; onClose: () => void; onSaved: () => Promise<void>;onTrashed:(note:Note)=>void }) {
  useEffect(() => {
    if (!offlineCaptureEnabled()) return;
    let cancelled = false;
    void api.noteDocument(note.id, "yjs_update").then(async snapshot => {
      if (cancelled || !offlineCaptureEnabled() || typeof snapshot.content !== "string") return;
      await cacheNoteSnapshot({ noteId: note.id, revisionId: snapshot.revisionId, updateBase64: snapshot.content });
    }).catch(() => { /* Snapshot caching does not acknowledge or save editor changes. */ });
    return () => { cancelled = true; };
  }, [note.id, note.revision]);
  const [document,setDocument]=useState<EditorDocument|null>(null);const expectedRevision=useRef(note.revision);
  const [revisions,setRevisions]=useState<NoteRevision[]>([]);
  const [attachments,setAttachments]=useState<BlobSummary[]>([]);
  const [classification, setClassification] = useState<NonNullable<Note["classification"]>>(note.classification ?? "unknown");
  const [lockClassification, setLockClassification] = useState(note.classificationLocked);
  const [labels, setLabels] = useState<Label[]>([]);
  const [assignedLabelIds, setAssignedLabelIds] = useState<string[]>([]);
  const [lockedLabelIds, setLockedLabelIds] = useState<string[]>([]);
  const [newLabel, setNewLabel] = useState("");
  const [otherNotes, setOtherNotes] = useState<Note[]>([]);
  const [relationships, setRelationships] = useState<Relationship[]>([]);
  const [relatedSuggestions, setRelatedSuggestions] = useState<Array<{noteId:string;title:string;score:number;sharedLabelIds:string[]}>>([]);
  const [relationshipTarget, setRelationshipTarget] = useState("");
  const [relationshipKind, setRelationshipKind] = useState<Relationship["kind"]>("related");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  useEffect(()=>{expectedRevision.current=Math.max(expectedRevision.current,note.revision);},[note.revision]);
  useEffect(() => { let cancelled=false;void Promise.all([api.labels(), api.noteLabels(note.id), api.notes(), api.relatedNotes(note.id),api.noteDocument(note.id,"editor_json"),api.noteRevisions(note.id)]).then(([available, organization, allNotes, related,representation,history]) => { if(cancelled)return;setLabels(available.items); setAssignedLabelIds(organization.labels.map(label => label.id)); setLockedLabelIds(organization.labels.filter(label => label.locked).map(label => label.id)); setOtherNotes(allNotes.items.filter(candidate => candidate.id !== note.id)); setRelationships(related.explicitLinks); setRelatedSuggestions(related.suggestedLinks); setDocument(editorDocumentSchema.parse(representation.content));setRevisions(history.items); }).catch(async caught => {
    if(cancelled)return;
    let canonicalDenied=false;
    try{
      const {canUseOfflineNote,isNoteAccessDenied,loadCachedNoteDocument,loadNoteSnapshot}=await import("./cached-shared-note");
      // An ancillary request failing first must not mask a canonical-note denial.
      if(canUseOfflineNote(caught)||isNoteAccessDenied(caught))await loadNoteSnapshot(note.id);
      const cached=canUseOfflineNote(caught)?await loadCachedNoteDocument(note.id):null;
      if(cancelled)return;
      if(cached){setDocument(cached);setError("Offline: showing this device's saved note. History and organization are unavailable until reconnect.");return;}
    }catch(error){
      const {isNoteAccessDenied}=await import("./cached-shared-note");
      canonicalDenied=isNoteAccessDenied(error);
    }
    if(!cancelled)setError(canonicalDenied?"Access to this note is unavailable. Its cached document will not be opened.":"Could not load the canonical note document, history, and organization.");
  });return()=>{cancelled=true;}; }, [note.id]);
  useEffect(()=>{if(!note.sourceId){setAttachments([]);return;}void api.captureDetails(note.sourceId).then(value=>setAttachments(value.blobs)).catch(()=>setAttachments([]));},[note.sourceId]);
  async function saveDocument(next: EditorDocument) {
    setBusy(true);
    setError(null);
    try {
      const revision = await api.editNoteDocument(note.id, expectedRevision.current, next);
      expectedRevision.current = revision.revision;
      try {
        setRevisions((await api.noteRevisions(note.id)).items);
        await onSaved();
      } catch {
        setError("Your note was saved, but refreshing its history or the note list failed. Reopen it to refresh.");
      }
    } finally {
      setBusy(false);
    }
  }
  function currentNote(){return {...note,revision:expectedRevision.current};}
  async function correctClassification() { setBusy(true); setError(null); try { await api.correctNoteClassification(currentNote(), classification, lockClassification); await onSaved(); } catch { setError("The classification correction was not saved."); } finally { setBusy(false); } }
  async function saveLabels() { setBusy(true); setError(null); try { await api.setNoteLabels(currentNote(), assignedLabelIds, lockedLabelIds.filter(id => assignedLabelIds.includes(id))); await onSaved(); } catch { setError("The label changes were not saved."); } finally { setBusy(false); } }
  async function addLabel() { if (!newLabel.trim()) return; try { const created = await api.createLabel(newLabel.trim()); setLabels(current => [...current, created]); setAssignedLabelIds(current => [...current, created.id]); setLockedLabelIds(current => [...current, created.id]); setNewLabel(""); } catch { setError("That label could not be created. It may already exist."); } }
  async function addRelationship() { if (!relationshipTarget) return; try { const created = await api.createRelationship(note.id, relationshipTarget, relationshipKind); setRelationships(current => [...current, created]); setRelatedSuggestions(current=>current.filter(item=>item.noteId!==relationshipTarget)); setRelationshipTarget(""); } catch { setError("That relationship could not be created."); } }
  async function reprocess() { setBusy(true); setError(null); try { await api.reprocessNote(currentNote()); setError("Reprocessing is queued for the approved local worker. Owner locks will be preserved."); } catch (caught) { setError(caught instanceof ApiError && caught.code === "stale_revision" ? "This note changed elsewhere. Reopen it before reprocessing." : "Reprocessing could not be queued."); } finally { setBusy(false); } }
  async function canReplaceNoteContent(){
    if(!allowEditorNavigation())return false;
    const [pending,conflicts]=await Promise.all([pendingSyncOperations(),syncConflicts()]);
    if(pending.some(row=>row.operation.type==="note_yjs_update"&&row.operation.noteId===note.id)
      ||conflicts.some(row=>row.operation?.type==="note_yjs_update"&&row.operation.noteId===note.id)){
      setError("Sync this note and resolve its offline conflicts before restoring a revision or moving it to trash.");
      return false;
    }
    return true;
  }
  async function trash(){if(!await canReplaceNoteContent())return;setBusy(true);setError(null);try{const current=expectedRevision.current;await api.trashNote(note.id,current);onTrashed({...note,revision:current+1});}catch(caught){setError(caught instanceof ApiError&&caught.code==="stale_revision"?"This note changed elsewhere. Reopen it before moving it to trash.":"The note could not be moved to trash.");}finally{setBusy(false);}}
  async function restoreRevision(revision:NoteRevision){if(revision.revision===expectedRevision.current||!await canReplaceNoteContent())return;setBusy(true);setError(null);try{const restored=await api.restoreNoteRevision(note.id,revision.id,expectedRevision.current);expectedRevision.current=restored.revision;const [history,representation]=await Promise.all([api.noteRevisions(note.id),api.noteDocument(note.id,"editor_json")]);setRevisions(history.items);setDocument(editorDocumentSchema.parse(representation.content));await onSaved();}catch(caught){setError(caught instanceof ApiError&&caught.code==="stale_revision"?"This note changed elsewhere. Reopen it before restoring history.":"That historical revision could not be restored.");}finally{setBusy(false);}}
  const classificationChanged = classification !== (note.classification ?? "unknown") || lockClassification !== note.classificationLocked;
  return <div className="editor-shell"><div className="editor-toolbar"><button className="icon-button" onClick={onClose} aria-label="Close editor"><X/></button><div><p className="eyebrow">Revision {expectedRevision.current}</p><h1>{note.title}</h1></div><button className="text-button" onClick={() => void reprocess()} disabled={busy}>Reprocess</button><button className="text-button danger" onClick={()=>void trash()} disabled={busy}>Move to trash</button></div>{error && <p className="form-error">{error}</p>}<div className="classification-bar"><label>Classification<select value={classification} onChange={event => setClassification(event.target.value as typeof classification)}><option value="note">Note</option><option value="task">Task</option><option value="event">Event</option><option value="idea">Idea</option><option value="reference">Reference</option><option value="unknown">Unknown</option></select></label><label className="lock-field"><input type="checkbox" checked={lockClassification} onChange={event => setLockClassification(event.target.checked)}/> Lock my choice against reprocessing</label><button className="text-button" disabled={!classificationChanged || busy} onClick={() => void correctClassification()}>Save classification</button>{note.suggestedTitle && <small>Suggested title: {note.suggestedTitle}</small>}</div><div className="organization-bar"><div className="label-pills">{labels.map(label => <label key={label.id} title={lockedLabelIds.includes(label.id) ? "Owner-locked label" : "Label"} className={assignedLabelIds.includes(label.id) ? "label-pill selected" : "label-pill"}><input type="checkbox" checked={assignedLabelIds.includes(label.id)} onChange={event => { setAssignedLabelIds(current => event.target.checked ? [...new Set([...current, label.id])] : current.filter(id => id !== label.id)); setLockedLabelIds(current => event.target.checked ? [...new Set([...current, label.id])] : current.filter(id => id !== label.id)); }}/>{label.name}{lockedLabelIds.includes(label.id) ? " · locked" : ""}</label>)}</div><div className="new-label"><input value={newLabel} onChange={event => setNewLabel(event.target.value)} placeholder="New topic label…"/><button onClick={() => void addLabel()} disabled={!newLabel.trim()}>Add + lock</button><button className="text-button" onClick={() => void saveLabels()} disabled={busy}>Save labels</button></div></div><div className="relationship-bar"><div>{relationships.map(link => <button key={link.id} onClick={async () => { await api.deleteRelationship(link); setRelationships(current => current.filter(item => item.id !== link.id)); }} title="Remove confirmed relationship">{link.kind.replace("_", " ")} · {otherNotes.find(candidate => candidate.id === (link.fromNoteId === note.id ? link.toNoteId : link.fromNoteId))?.title ?? "linked note"} ×</button>)}</div>{relatedSuggestions.length>0&&<div aria-label="Similarity suggestions"><small>Suggestions, not confirmed links:</small>{relatedSuggestions.map(item=><button key={item.noteId} type="button" className="text-button" onClick={()=>setRelationshipTarget(item.noteId)} title={`Similarity suggestion from shared confirmed labels; ${Math.round(item.score*100)}% Jaccard score`}>{item.title} · suggested {Math.round(item.score*100)}%</button>)}</div>}<select value={relationshipKind} onChange={event => setRelationshipKind(event.target.value as Relationship["kind"])}><option value="related">Related</option><option value="supports">Supports</option><option value="contradicts">Contradicts</option><option value="duplicate_candidate">Possible duplicate</option></select><select value={relationshipTarget} onChange={event => setRelationshipTarget(event.target.value)}><option value="">Choose a note…</option>{otherNotes.map(candidate => <option value={candidate.id} key={candidate.id}>{candidate.title}</option>)}</select><button onClick={() => void addRelationship()} disabled={!relationshipTarget}>Link</button></div>{attachments.length>0&&<section className="note-attachments"><div className="card-label"><Paperclip size={16}/> Original attachments</div>{attachments.map(item=><article key={item.id}>{item.mediaType.startsWith("image/")&&!item.mediaType.includes("hei")&&<img src={api.blobContentUrl(item.id)} alt=""/>}<div><strong>{item.filename}</strong><small>{item.mediaType} · {(item.byteLength/1024).toFixed(item.byteLength<10240?1:0)} KB · SHA-256 {item.sha256.slice(0,12)}…</small></div><a className="text-button" href={api.blobContentUrl(item.id,true)}>Download original</a></article>)}</section>}{document?<Suspense fallback={<div className="editor-loading">Loading rich editor…</div>}><RichDocumentEditor key={note.id} noteId={note.id} revision={expectedRevision.current} initialDocument={document} disabled={busy} onSave={saveDocument} onSharedSaved={onSaved}/></Suspense>:<div className="editor-loading">Loading canonical document…</div>}<details className="revision-history"><summary>Revision history · {revisions.length}</summary>{revisions.map(revision=><article key={revision.id}><strong>Revision {revision.revision}</strong><span>{revision.actorKind} · {friendlyDate(revision.createdAt)}</span><p>{revision.text.slice(0,240)}{revision.text.length>240?"…":""}</p>{revision.revision!==expectedRevision.current&&<button className="text-button" disabled={busy} onClick={()=>void restoreRevision(revision)}>Restore as new revision</button>}</article>)}</details><div className="editor-footer"><span>Autosave creates immutable revisions.</span><span>The original capture remains linked.</span></div></div>;
}

function RemindersWorkspace({tasks,refreshTasks}:{tasks:Task[];refreshTasks:()=>Promise<void>}){
  const [reminders,setReminders]=useState<Reminder[]>([]);const [notifications,setNotifications]=useState<Notification[]>([]);const [taskId,setTaskId]=useState("");const [remindAt,setRemindAt]=useState("");const [channel,setChannel]=useState<Reminder["channel"]>("in_app");const [error,setError]=useState<string|null>(null);const [busy,setBusy]=useState(false);
  async function refresh(){const [nextReminders,nextNotifications]=await Promise.all([api.reminders(),api.notifications()]);setReminders(nextReminders.items);setNotifications(nextNotifications.items);setTaskId(current=>current||tasks.find(task=>!task.completed)?.id||tasks[0]?.id||"");}
  useEffect(()=>{void refresh().catch(()=>setError("Reminders and notifications are unavailable."));},[tasks.length]);
  async function create(event:FormEvent){event.preventDefault();if(!remindAt)return;setBusy(true);setError(null);try{await api.createReminder(taskId||null,new Date(remindAt).toISOString(),Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC",channel);setRemindAt("");await refresh();}catch{setError("The reminder was not saved. Choose a future time and a current task.");}finally{setBusy(false);}}
  async function dismiss(item:Reminder){try{await api.updateReminder(item,{status:"dismissed"});await refresh();}catch{setError("The reminder changed elsewhere and was not dismissed.");}}
  async function snooze(item:Reminder){const value=window.prompt("Snooze until (YYYY-MM-DDTHH:mm)");if(!value)return;const parsed=new Date(value);if(Number.isNaN(parsed.getTime()))return setError("Enter a valid local date and time.");try{await api.updateReminder(item,{status:"snoozed",remindAt:parsed.toISOString()});await refresh();}catch{setError("The reminder could not be snoozed to that time.");}}
  async function remove(item:Reminder){try{await api.deleteReminder(item);await refresh();}catch{setError("The reminder changed elsewhere and was not cancelled.");}}
  async function acknowledge(item:Notification,state:"read"|"dismissed"){try{await api.updateNotification(item.id,state);await refresh();}catch{setError("The notification acknowledgement was not saved.");}}
  async function removeTask(item:Task){try{await api.deleteTask(item);await refreshTasks();await refresh();}catch{setError("The task changed elsewhere and was not deleted. Its source note, if any, was left untouched.");}}
  return <section className="settings-panel school-assignments"><div className="card-label"><Clock3 size={16}/> Reminders and notification acknowledgements</div><p className="panel-copy">Schedules are explicit and synchronized. “Delivered” means the reminder reached Sorta’s durable notification queue; operating-system desktop display still requires the packaged Windows host service to be live-verified.</p>{error&&<p className="form-error">{error}</p>}<form className="assignment-form" onSubmit={create}><select value={taskId} onChange={event=>setTaskId(event.target.value)}><option value="">Standalone reminder</option>{tasks.filter(task=>!task.completed).map(task=><option key={task.id} value={task.id}>{task.title}</option>)}</select><input type="datetime-local" value={remindAt} onChange={event=>setRemindAt(event.target.value)} required/><select value={channel} onChange={event=>setChannel(event.target.value as Reminder["channel"])}><option value="in_app">In app</option><option value="desktop">Desktop queue</option></select><button className="primary" disabled={busy||!remindAt}>{busy?"Saving…":"Schedule reminder"}</button></form><div className="settings-list">{reminders.map(item=><article key={item.id}><div><strong>{tasks.find(task=>task.id===item.taskId)?.title??"Standalone reminder"} · {item.status}</strong><small>{friendlyDate(item.remindAt)} · {item.timezone} · {item.channel.replace("_"," ")} · revision {item.revision}</small></div><div className="session-actions">{["delivered","missed"].includes(item.status)&&<button className="text-button" onClick={()=>void snooze(item)}>Snooze</button>}{item.status!=="dismissed"&&<button className="text-button" onClick={()=>void dismiss(item)}>Dismiss</button>}<button className="text-button danger" onClick={()=>void remove(item)}>Cancel</button></div></article>)}{!reminders.length&&<p className="quiet-empty">No scheduled or retained reminders.</p>}</div><div className="settings-list">{notifications.map(item=><article key={item.id}><div><strong>{item.title} · {item.state}</strong><small>{item.body} · queued {friendlyDate(item.deliveredAt)} · {item.channel.replace("_"," ")}</small></div><div className="session-actions">{item.state==="unread"&&<button className="text-button" onClick={()=>void acknowledge(item,"read")}>Mark read</button>}{item.state!=="dismissed"&&<button className="text-button danger" onClick={()=>void acknowledge(item,"dismissed")}>Dismiss</button>}</div></article>)}{!notifications.length&&<p className="quiet-empty">No durable notifications have become due.</p>}</div><details><summary>Delete tasks</summary><p className="panel-copy">Deleting a task cancels its future reminders but keeps source notes and historical schedule/session evidence.</p>{tasks.map(task=><button key={task.id} className="text-button danger" onClick={()=>void removeTask(task)}>Delete “{task.title}”</button>)}</details></section>;
}

function TasksView({ tasks, people, commitments, taskTitle, setTaskTitle, busy, submitTask, refresh, toggleTask }: { tasks: Task[]; people: CalendarEntity[]; commitments: Commitment[]; taskTitle: string; setTaskTitle: (value: string) => void; busy: boolean; submitTask: (event: FormEvent) => Promise<void>; refresh: () => Promise<void>; toggleTask:(task:Task)=>Promise<void> }) {
  const [personName, setPersonName] = useState("");
  const [personId, setPersonId] = useState("");
  const [objectLabel, setObjectLabel] = useState("");
  const [promiseText, setPromiseText] = useState("");
  const [executionHistory,setExecutionHistory]=useState<TaskExecutionHistory|null>(null);
  const [historyError,setHistoryError]=useState<string|null>(null);
  const [commitmentNotice,setCommitmentNotice]=useState<string|null>(null);
  const [commitmentError,setCommitmentError]=useState<string|null>(null);

  async function addPerson(event: FormEvent) {
    event.preventDefault();
    if (!personName.trim()) return;
    const person = await api.createEntity("person", personName.trim());
    setPersonName(""); setPersonId(person.id); await refresh();
  }

  async function addCommitment(event: FormEvent) {
    event.preventDefault();
    if (!personId || !objectLabel.trim() || !promiseText.trim()) return;
    await api.createCommitment({ text: promiseText.trim(), personEntityId: personId, objectLabel: objectLabel.trim() });
    setObjectLabel(""); setPromiseText(""); await refresh();
  }

  async function showExecutionHistory(task:Task){setHistoryError(null);try{setExecutionHistory(await api.taskExecutionHistory(task.id));}catch{setHistoryError("Recorded work history could not be loaded.");}}
  async function transitionCommitment(item:Commitment,status:"fulfilled"|"cancelled"){setCommitmentError(null);setCommitmentNotice(null);try{await api.updateCommitmentStatus(item,status,status==="fulfilled"?"Owner confirmed the promised action was completed":"Owner cancelled the promise");setCommitmentNotice(status==="fulfilled"?"Promise marked fulfilled from explicit owner confirmation.":"Promise cancelled from explicit owner confirmation.");await refresh();}catch{setCommitmentError("The promise changed elsewhere or the transition could not be verified. Refresh and try again.");}}
  async function rematchCommitment(item:Commitment){setCommitmentError(null);setCommitmentNotice(null);try{await api.rematchCommitment(item);setCommitmentNotice("Future meetings were checked deterministically; existing bindings were not duplicated.");await refresh();}catch{setCommitmentError("The promise could not be rematched at its current revision.");}}
  async function archiveCommitment(item:Commitment){if(!window.confirm("Archive this promise? Its source evidence and history will be preserved, while future preparation bindings are removed."))return;setCommitmentError(null);setCommitmentNotice(null);try{await api.archiveCommitment(item);setCommitmentNotice("Promise archived; source evidence and status history were preserved.");await refresh();}catch{setCommitmentError("The promise changed elsewhere and was not archived.");}}

  const personNameById = new Map(people.map(person => [person.id, person.name]));
  return <><PageTitle eyebrow="Tasks and promises" title="Commitments" copy="Ordinary work and unfinished promises stay distinct, but live in one place."/><div className="split-grid"><section><h2>Tasks</h2><form className="inline-form" onSubmit={submitTask}><input value={taskTitle} onChange={event => setTaskTitle(event.target.value)} placeholder="Add a task…"/><button className="primary" disabled={busy || !taskTitle.trim()}><Plus size={18}/> Add</button></form><div className="list-card">{tasks.map(task => <div className="task-with-history" key={task.id}><TaskRow task={task} onToggle={()=>toggleTask(task)}/><button className="text-button" onClick={()=>void showExecutionHistory(task)}>Work history</button></div>)}</div>{historyError&&<p className="form-error">{historyError}</p>}{executionHistory&&<div className="rule-preview"><strong>{tasks.find(task=>task.id===executionHistory.taskId)?.title??"Task"} · recorded work</strong>{executionHistory.items.map(session=><span key={session.id}>{session.state.replaceAll("_"," ")} · {Math.floor(session.observedActiveSeconds/60)} measured min · {session.actions.map(action=>action.action).join(" → ")}{session.actionsTruncated?" · older actions omitted":""}</span>)}{!executionHistory.items.length&&<span>No explicit start, pause, resume, interruption, completion, or skip has been recorded for this task.</span>}<small>Calendar presence is not included as work. Completion time is not evidence of mastery.</small></div>}</section><section><h2>Conditional promises</h2>{people.length === 0 && <form className="inline-form" onSubmit={addPerson}><input value={personName} onChange={event => setPersonName(event.target.value)} placeholder="Add a person first…"/><button className="primary" disabled={!personName.trim()}><Plus size={18}/> Person</button></form>}<form className="promise-form" onSubmit={addCommitment}><label>Person<select value={personId} onChange={event => setPersonId(event.target.value)} required><option value="">Choose a person</option>{people.map(person => <option key={person.id} value={person.id}>{person.name}</option>)}</select></label><label>What must you bring?<input value={objectLabel} onChange={event => setObjectLabel(event.target.value)} placeholder="the borrowed economics book" required/></label><label>Original promise<input value={promiseText} onChange={event => setPromiseText(event.target.value)} placeholder="Return the book next time I meet Hanako" required/></label><button className="primary" disabled={!personId || !objectLabel.trim() || !promiseText.trim()}>Remember this promise</button></form>{commitmentError&&<p className="form-error">{commitmentError}</p>}{commitmentNotice&&<p className="success-banner">{commitmentNotice}</p>}<div className="commitment-list">{commitments.map(item => <article key={item.id}><span className="commitment-icon">↗</span><div><strong>{item.text}</strong><p>When you next meet {personNameById.get(item.personEntityId) ?? "this person"} · no invented date</p><div className="commitment-actions"><button className="text-button" onClick={()=>void rematchCommitment(item)}>Check meetings</button><button className="text-button" onClick={()=>void transitionCommitment(item,"fulfilled")}>Mark fulfilled</button><button className="text-button danger" onClick={()=>void transitionCommitment(item,"cancelled")}>Cancel</button><button className="text-button danger" onClick={()=>void archiveCommitment(item)}>Archive</button></div></div></article>)}{commitments.length === 0 && <p className="quiet-empty">No active conditional promises.</p>}</div></section></div></>;
}

function calendarProjectionRange(mode:CalendarViewData["view"],cursor:Date){const start=new Date(cursor);start.setHours(0,0,0,0);if(mode==="week"||mode==="workweek"){start.setDate(start.getDate()-((start.getDay()+6)%7));}else if(mode==="month"){start.setDate(1);start.setDate(start.getDate()-((start.getDay()+6)%7));}const end=new Date(start);end.setDate(end.getDate()+(mode==="day"?1:mode==="week"?7:mode==="workweek"?5:mode==="month"?42:90));return{from:start.toISOString(),to:end.toISOString()};}
function calendarDateKey(value:string,timezone:string){const parts=new Intl.DateTimeFormat("en-CA",{timeZone:timezone,year:"numeric",month:"2-digit",day:"2-digit"}).formatToParts(new Date(value));const part=(type:Intl.DateTimeFormatPartTypes)=>parts.find(item=>item.type===type)?.value??"";return`${part("year")}-${part("month")}-${part("day")}`;}

function CalendarProjection({eventCount}:{eventCount:number}){
  const [mode,setMode]=useState<CalendarViewData["view"]>("week");const [cursor,setCursor]=useState(()=>new Date());const [data,setData]=useState<CalendarViewData|null>(null);const [error,setError]=useState<string|null>(null);const [busy,setBusy]=useState(false);const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC";
  async function refresh(){setBusy(true);setError(null);try{const range=calendarProjectionRange(mode,cursor);setData(await api.calendarView(range.from,range.to,timezone,mode,[]));}catch{setError("The bounded calendar view could not be loaded.");}finally{setBusy(false);}}
  useEffect(()=>{void refresh();},[mode,cursor.getTime(),eventCount]);
  useEffect(()=>{const changed=()=>void refresh();window.addEventListener("calendar-sources-changed",changed);return()=>window.removeEventListener("calendar-sources-changed",changed);},[mode,cursor.getTime()]);
  function move(direction:number){const next=new Date(cursor);if(mode==="month")next.setMonth(next.getMonth()+direction);else next.setDate(next.getDate()+direction*(mode==="day"?1:mode==="agenda"?30:7));setCursor(next);}
  const days=useMemo(()=>{if(!data||mode==="agenda")return[];const result:Date[]=[];const current=new Date(data.range.from);while(current<new Date(data.range.to)){result.push(new Date(current));current.setDate(current.getDate()+1);}return result;},[data,mode]);
  const items=useMemo(()=>{if(!data)return[];return[...data.occurrences.map(item=>({id:item.id,title:item.title,startsAt:item.startsAt,endsAt:item.endsAt,layer:item.layer,detail:`${item.source.kind} · revision ${item.eventRevision}`,eventId:item.eventId})),...data.overlayItems.map(item=>({id:`overlay-${item.id}`,title:item.title,startsAt:item.startsAt,endsAt:item.endsAt,layer:item.layer,detail:`${item.kind.replaceAll("_"," ")} · source record · revision ${item.revision}`,eventId:null}))].sort((a,b)=>a.startsAt.localeCompare(b.startsAt)||a.id.localeCompare(b.id));},[data]);
  return <section className="calendar-projection"><div className="calendar-view-toolbar"><div><strong>Calendar view</strong><small>{data?`${friendlyDate(data.range.from)} – ${friendlyDate(data.range.to)}`:"Loading bounded range…"}</small></div><div className="calendar-view-modes">{(["day","week","workweek","month","agenda"] as const).map(value=><button className={mode===value?"active":""} key={value} onClick={()=>setMode(value)}>{value}</button>)}</div><div className="calendar-nav"><button onClick={()=>move(-1)} aria-label="Previous calendar range">←</button><button onClick={()=>setCursor(new Date())}>Today</button><button onClick={()=>move(1)} aria-label="Next calendar range">→</button></div></div>{error&&<p className="form-error">{error}</p>}{busy&&!data&&<p className="quiet-empty">Loading calendar projection…</p>}{data?.staleSources.length?<div className="conflict-banner"><strong>{data.staleSources.length} calendar source{data.staleSources.length===1?" needs":"s need"} attention</strong>{data.staleSources.map(source=><span key={source.connectionId}>{source.label}: {source.reason.replaceAll("_"," ")}</span>)}</div>:null}{mode==="agenda"?<div className="calendar-agenda">{items.map(item=><article key={item.id}><time>{friendlyDate(item.startsAt)}</time><div><strong>{item.title}</strong><small>{item.layer} · {item.detail}</small></div></article>)}{!items.length&&<p className="quiet-empty">No timed items in this agenda range.</p>}</div>:<div className={`calendar-grid calendar-grid-${mode}`}>{days.map(day=>{const key=calendarDateKey(day.toISOString(),timezone);const dayItems=items.filter(item=>calendarDateKey(item.startsAt,timezone)===key);return <section className={calendarDateKey(new Date().toISOString(),timezone)===key?"calendar-day today":"calendar-day"} key={key}><header><span>{new Intl.DateTimeFormat(undefined,{weekday:"short",timeZone:timezone}).format(day)}</span><strong>{new Intl.DateTimeFormat(undefined,{day:"numeric",month:mode==="month"?"short":undefined,timeZone:timezone}).format(day)}</strong></header><div>{dayItems.map(item=><article className={`calendar-block ${item.layer}`} key={item.id} title={item.detail}><time>{new Intl.DateTimeFormat(undefined,{hour:"2-digit",minute:"2-digit",timeZone:timezone}).format(new Date(item.startsAt))}</time><strong>{item.title}</strong><small>{item.layer}</small></article>)}{!dayItems.length&&<span className="calendar-day-empty">—</span>}</div></section>;})}</div>}{data?.unknownTimeMarkers.length?<details className="calendar-unknown"><summary>{data.unknownTimeMarkers.length} school record{data.unknownTimeMarkers.length===1?" has":"s have"} unresolved time</summary>{data.unknownTimeMarkers.map(item=><p key={`${item.kind}-${item.id}`}><strong>{item.title}</strong> · {item.kind} · {item.date??"date unknown"} · {item.reason.replaceAll("_"," ")}</p>)}</details>:null}</section>;
}

function CalendarSourcesWorkspace(){
  const [items,setItems]=useState<CalendarRecord[]>([]);const [name,setName]=useState("");const [color,setColor]=useState("#6366f1");const [error,setError]=useState<string|null>(null);const [notice,setNotice]=useState<string|null>(null);const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC";
  async function refresh(){setItems((await api.calendars()).items);}
  useEffect(()=>{void refresh().catch(()=>setError("Calendar sources could not be loaded."));},[]);
  async function create(event:FormEvent){event.preventDefault();if(!name.trim())return;setError(null);try{await api.createCalendar(name.trim(),timezone,color);setName("");setNotice("Private Sorta calendar created. No provider calendar was created.");await refresh();window.dispatchEvent(new Event("calendar-sources-changed"));}catch{setError("The private calendar could not be created.");}}
  async function setVisible(item:CalendarRecord,selectedVisible:boolean){setError(null);try{await api.updateCalendar(item,{selectedVisible});await refresh();window.dispatchEvent(new Event("calendar-sources-changed"));}catch{setError("Visibility changed elsewhere. Refresh and try again.");}}
  async function archive(item:CalendarRecord){if(!window.confirm(`Archive “${item.name}” locally? Its events and provider source stay intact, and no external deletion will be sent.`))return;setError(null);try{await api.archiveCalendar(item);setNotice("Calendar archived locally. No external deletion was requested; Undo remains available below.");await refresh();window.dispatchEvent(new Event("calendar-sources-changed"));}catch{setError("The calendar changed elsewhere and was not archived.");}}
  async function restore(item:CalendarRecord){setError(null);try{await api.updateCalendar(item,{archived:false,selectedVisible:true});setNotice("Calendar restored from its local tombstone.");await refresh();window.dispatchEvent(new Event("calendar-sources-changed"));}catch{setError("The calendar tombstone changed and could not be restored.");}}
  return <section className="settings-panel school-assignments"><div className="card-label"><CalendarDays size={16}/> Calendars</div><p className="panel-copy">Visibility is local to Sorta. Provider calendars remain read-only here; creating or archiving a Sorta calendar never creates or deletes one at Microsoft, Google, or InSchool.</p>{error&&<p className="form-error">{error}</p>}{notice&&<p className="success-banner">{notice}</p>}<form className="assignment-form" onSubmit={create}><input value={name} onChange={event=>setName(event.target.value)} placeholder="New private calendar"/><input type="color" value={color} onChange={event=>setColor(event.target.value)} aria-label="Calendar color"/><button className="primary" disabled={!name.trim()}>Create calendar</button></form><div className="settings-list">{items.map(item=><article key={item.id}><div><strong>{item.name} · {item.origin.replaceAll("_"," ")}</strong><small>{item.ownership} · {item.capabilities.write?"read/write":"read-only"} · {item.freshness.state.replaceAll("_"," ")} · revision {item.revision}</small>{item.providerMapping&&<small>Provider mapping {item.providerMapping.providerCalendarId} · connection {item.providerMapping.connectionId.slice(0,8)}</small>}</div><div className="session-actions">{item.archivedAt?<button className="text-button" onClick={()=>void restore(item)}>Undo archive</button>:<><label className="repeat-toggle"><input type="checkbox" checked={item.selectedVisible} onChange={event=>void setVisible(item,event.target.checked)}/> Visible</label><button className="text-button danger" onClick={()=>void archive(item)}>Archive locally</button></>}</div></article>)}</div></section>;
}

function CalendarDailyBrief(){const [brief,setBrief]=useState<CalendarBrief|null>(null);const [error,setError]=useState<string|null>(null);const [busy,setBusy]=useState(false);const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC";const date=new Intl.DateTimeFormat("en-CA",{timeZone:timezone,year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date());async function load(){setBrief(await api.calendarBrief(date,timezone));}useEffect(()=>{void load().catch(()=>setError("Today’s calendar brief could not be loaded."));},[]);async function refresh(){setBusy(true);setError(null);try{await api.refreshCalendarBrief(date,timezone);await load();}catch{setError("The bounded calendar brief refresh did not finish.");}finally{setBusy(false);}}return <section className="settings-panel"><div className="card-label"><Sparkles size={16}/> Today’s calendar brief</div>{error&&<p className="form-error">{error}</p>}{brief?<><p className="panel-copy">{brief.deterministicSummary.join(" ")}</p><small>{brief.state} · {brief.generation.sourceCount} source event(s) · {brief.generatedAt?`generated ${friendlyDate(brief.generatedAt)}`:"not cached yet"}</small><div className="settings-list">{brief.items.slice(0,6).map(item=><article key={item.occurrenceId}><div><strong>{item.title}</strong><small>{friendlyDate(item.startsAt)} · {item.prepItemCount} prep · {item.linkedCommitmentCount} promise(s)</small></div></article>)}</div></>:<p className="quiet-empty">Loading source-linked brief…</p>}<button className="text-button" disabled={busy} onClick={()=>void refresh()}>{busy?"Refreshing…":"Refresh cached brief"}</button></section>;}

function CalendarImportWorkspace(){const [calendars,setCalendars]=useState<CalendarRecord[]>([]);const [target,setTarget]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState<string|null>(null);const [result,setResult]=useState<{proposalId:string;counts:Record<string,number>;warnings:string[]}|null>(null);const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||"UTC";useEffect(()=>{void api.calendars().then(response=>{const writable=response.items.filter(item=>!item.archivedAt&&item.capabilities.write);setCalendars(writable);setTarget(writable[0]?.id??"");}).catch(()=>setError("Writable calendars could not be loaded."));},[]);async function select(file:File){if(!target)return;setBusy(true);setError(null);setResult(null);try{if(!file.name.toLowerCase().endsWith(".ics")||file.size>10*1024*1024)throw new Error("invalid_ics_file");const blob=await api.uploadFile(file),handle=await api.previewCalendarImport(blob.id,timezone,target),job=await api.job(handle.id);if(job.result?.type!=="calendar_import_preview")throw new Error("preview_not_ready");setResult({proposalId:job.result.proposalId,counts:job.result.counts,warnings:job.result.warnings});}catch{setError("The ICS preview failed. The file must be a valid calendar no larger than 10 MB; nothing was imported.");}finally{setBusy(false);}}return <section className="settings-panel"><div className="card-label"><CalendarDays size={16}/> Calendar import preview</div><p className="panel-copy">Upload an `.ics` file to review creates, weekly series, duplicates, cancellations, and blocked records. Preview never writes events and ignores organizer, attendee, RSVP, meeting-request, and response semantics.</p><div className="assignment-form"><select value={target} onChange={event=>{setTarget(event.target.value);setResult(null);}}><option value="">Choose writable calendar</option>{calendars.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select><label className="text-button file-button">{busy?"Parsing safely…":"Choose .ics for preview"}<input type="file" accept=".ics,text/calendar" disabled={busy||!target} onChange={event=>{const file=event.target.files?.[0];event.target.value="";if(file)void select(file);}}/></label></div>{error&&<p className="form-error">{error}</p>}{result&&<div className="rule-preview"><strong>Proposal {result.proposalId.slice(0,8)} · no calendar writes</strong><span>{result.counts.create??0} create · {result.counts.createSeries??0} weekly series · {result.counts.cancel??0} cancel · {result.counts.duplicate??0} duplicate · {result.counts.blocked??0} blocked</span>{result.warnings.map((warning,index)=><small key={index}>{warning}</small>)}<small>No invitations or responses were sent.</small></div>}</section>;}

function CalendarExportWorkspace(){const [calendars,setCalendars]=useState<CalendarRecord[]>([]);const [selected,setSelected]=useState<string[]>([]);const [busy,setBusy]=useState(false);const [error,setError]=useState<string|null>(null);const [download,setDownload]=useState<{url:string;expiresAt:string;byteLength:number}|null>(null);useEffect(()=>{void api.calendars().then(result=>{const readable=result.items.filter(item=>!item.archivedAt&&item.capabilities.read);setCalendars(readable);setSelected(readable.filter(item=>item.selectedVisible).map(item=>item.id));}).catch(()=>setError("Calendars could not be loaded for export."));},[]);async function generate(){if(!selected.length)return;setBusy(true);setError(null);setDownload(null);try{const from=new Date(),to=new Date(from.getTime()+90*86_400_000),handle=await api.exportCalendar(selected,from.toISOString(),to.toISOString()),job=await api.job(handle.id);if(job.result?.type!=="export_generate")throw new Error("export_not_ready");const manifest=await api.exportManifest(job.result.exportId);if(manifest.status!=="ready"||manifest.byteLength===null)throw new Error("export_not_ready");setDownload({url:api.exportDownloadUrl(manifest.id),expiresAt:manifest.expiresAt,byteLength:manifest.byteLength});}catch{setError("The private calendar export could not be generated.");}finally{setBusy(false);}}function toggle(id:string,checked:boolean){setSelected(current=>checked?[...new Set([...current,id])]:current.filter(item=>item!==id));setDownload(null);}return <section className="settings-panel"><div className="card-label"><CalendarDays size={16}/> Private calendar export</div><p className="panel-copy">Create a 90-day iCalendar file from selected readable calendars. It includes occurrence times and titles only—private preparation, notes, reminders, commitments, attendees, school records, and profile data are omitted.</p>{calendars.map(item=><label className="repeat-toggle" key={item.id}><input type="checkbox" checked={selected.includes(item.id)} onChange={event=>toggle(item.id,event.target.checked)}/>{item.name}</label>)}{error&&<p className="form-error">{error}</p>}<div className="session-actions"><button className="text-button" disabled={busy||!selected.length} onClick={()=>void generate()}>{busy?"Generating…":"Generate minimal .ics"}</button>{download&&<a className="text-button" href={download.url} download>Download {Math.max(1,Math.ceil(download.byteLength/1024))} KB .ics</a>}</div>{download&&<small>Private download expires {friendlyDate(download.expiresAt)}. Authorization and checksum are rechecked when downloaded.</small>}</section>;}

function CalendarReminderWorkspace({events}:{events:CalendarEvent[]}){
  const [eventId,setEventId]=useState("");const [plan,setPlan]=useState<EventReminderPlan|null>(null);const [minutes,setMinutes]=useState(30);const [native,setNative]=useState(false);const [error,setError]=useState<string|null>(null);const [notice,setNotice]=useState<string|null>(null);const selected=events.find(item=>item.id===eventId);
  useEffect(()=>{if(!eventId&&events[0])setEventId(events[0].id);},[events,eventId]);
  useEffect(()=>{if(!eventId)return;void api.eventReminderPlan(eventId).then(setPlan).catch(()=>setError("Reminder plan could not be loaded."));},[eventId]);
  async function save(event:FormEvent){event.preventDefault();if(!eventId||!plan)return;setError(null);try{const updated=await api.setEventReminderPlan(eventId,plan.revision,minutes,native?["in_app","windows_native"]:["in_app"]);setPlan(updated);setNotice(updated.deliverability.windowsNative==="unverified_host_delivery"?"Plan saved. Windows delivery remains unverified until the packaged host is tested.":"Plan saved to the durable in-app queue policy.");}catch{setError("The reminder plan changed elsewhere or could not be saved.");}}
  async function refreshContext(){if(!selected)return;setError(null);try{const job=await api.refreshPrivateEventContext(selected);setNotice(`Private context refreshed by job ${job.id.slice(0,8)}. Only exact deterministic matches were applied.`);}catch{setError("Private context changed or could not be refreshed.");}}
  return <section className="settings-panel school-assignments"><div className="card-label"><Clock3 size={16}/> Event preparation and reminders</div><p className="panel-copy">Reminder plans expose their next triggers and delivery capability. Windows delivery is never shown as guaranteed before live host validation.</p>{error&&<p className="form-error">{error}</p>}{notice&&<p className="success-banner">{notice}</p>}<form className="assignment-form" onSubmit={save}><select value={eventId} onChange={event=>{setEventId(event.target.value);setPlan(null);}}><option value="">Choose event</option>{events.map(item=><option key={item.id} value={item.id}>{item.title}</option>)}</select><input type="number" min={0} max={10080} value={minutes} onChange={event=>setMinutes(Number(event.target.value))}/><label className="repeat-toggle"><input type="checkbox" checked={native} onChange={event=>setNative(event.target.checked)}/> Windows queue</label><button className="primary" disabled={!plan}>Save reminder</button><button type="button" className="text-button" disabled={!selected} onClick={()=>void refreshContext()}>Refresh private context</button></form>{plan&&<small>Plan revision {plan.revision} · {plan.nextTriggers.length} upcoming trigger(s) · OS delivery {plan.deliverability.guaranteedOsDelivery?"guaranteed":"not guaranteed"}</small>}</section>;
}

function PreparationPlanWorkspace({tasks,events}:{tasks:Task[];events:CalendarEvent[]}){const [notice,setNotice]=useState<string|null>(null);const [error,setError]=useState<string|null>(null);const [busy,setBusy]=useState(false);async function preview(){setBusy(true);setError(null);setNotice(null);try{const open=tasks.filter(task=>!task.completed);if(!open.length){setNotice("No open tasks need preparation time.");return;}const preferences=await api.schedulerPreferences();const startsAt=new Date().toISOString(),endsAt=new Date(Date.now()+7*86_400_000).toISOString();const locked=events.filter(event=>Date.parse(event.endsAt)>Date.now()&&Date.parse(event.startsAt)<Date.parse(endsAt));const job=await api.previewPreparationPlan(open,preferences,locked,startsAt,endsAt);setNotice(`Preparation proposal job ${job.id.slice(0,8)} is ready for review. No calendar event was created.`);}catch{setError("The preparation preview inputs changed or could not be scheduled.");}finally{setBusy(false);}}return <section className="settings-panel"><div className="card-label"><ListTodo size={16}/> Preparation plan</div><p className="panel-copy">Preview open work against the next seven days using recorded estimates and current fixed events. The result is a reviewable proposal; preview never changes the calendar.</p>{error&&<p className="form-error">{error}</p>}{notice&&<p className="success-banner">{notice}</p>}<button className="text-button" disabled={busy} onClick={()=>void preview()}>{busy?"Computing…":"Preview preparation time"}</button></section>;}

function ProviderCalendarOutboxWorkspace({events}:{events:CalendarEvent[]}){
  const [connections,setConnections]=useState<IntegrationConnection[]>([]);const [actions,setActions]=useState<ProviderCalendarAction[]>([]);const [connectionId,setConnectionId]=useState("");const [eventId,setEventId]=useState("");const [kind,setKind]=useState<"create"|"update"|"delete"|"respond">("create");const [targetCalendarId,setTargetCalendarId]=useState("");const [recipients,setRecipients]=useState("");const [response,setResponse]=useState<"accepted"|"declined"|"tentative">("accepted");const [proposal,setProposal]=useState<Proposal|null>(null);const [error,setError]=useState<string|null>(null);const [notice,setNotice]=useState<string|null>(null);
  async function refresh(){const [nextConnections,nextActions]=await Promise.all([api.connections(),api.providerCalendarActions()]);const calendars=nextConnections.items.filter(item=>["microsoft","google_calendar"].includes(item.provider)&&!item.disconnectedAt);setConnections(calendars);setActions(nextActions.items);setConnectionId(current=>current||calendars[0]?.id||"");setEventId(current=>current||events[0]?.id||"");}
  useEffect(()=>{void refresh().catch(()=>setError("Provider outbox records are unavailable."));},[events.length]);
  async function preview(event:FormEvent){event.preventDefault();const selected=events.find(item=>item.id===eventId);if(!selected||!connectionId||!targetCalendarId.trim())return;setError(null);setNotice(null);try{const addresses=recipients.split(",").map(value=>value.trim()).filter(Boolean);const created=await api.previewProviderCalendarAction(selected,connectionId,kind,targetCalendarId.trim(),addresses,kind==="respond"?response:null);if(created.kind!=="provider_calendar_action")throw new Error("wrong_proposal_kind");setProposal(created);}catch{setError("The exact provider action preview could not be created. Check recipient addresses and the selected connection.");}}
  async function accept(){if(!proposal||proposal.kind!=="provider_calendar_action")return;setError(null);try{const job=await api.acceptProviderCalendarProposal(proposal);setNotice(`Outbox action queued by job ${job.id.slice(0,8)}. This is not provider acknowledgement.`);setProposal(null);await refresh();}catch(caught){const code=caught instanceof ApiError?caught.code:"request_failed";setError(code==="provider_calendar_write_not_verified"||code==="provider_connection_not_connected"?"Nothing was queued: this connection has not passed a live provider-write capability test.":"The reviewed action became stale or could not be queued; no external write occurred.");}}
  async function cancel(action:ProviderCalendarAction){setError(null);try{await api.cancelProviderCalendarAction(action);await refresh();}catch{setError("Only an unchanged, unsent pending action can be cancelled. Sent or delivery-unknown work requires reviewed reconciliation or compensation.");}}
  const selectedEvent=events.find(item=>item.id===eventId);const selectedConnection=connections.find(item=>item.id===connectionId);
  return <section className="settings-panel school-assignments"><div className="card-label"><Zap size={16}/> External calendar outbox</div><p className="panel-copy">Preview exact public content and recipients before queuing a Microsoft or Google action. Private context, preparation, commitments, grades, attendance, profile facts, and source excerpts are always excluded. A queued action is not provider acknowledgement.</p>{error&&<p className="form-error">{error}</p>}{notice&&<p className="success-banner">{notice}</p>}<form className="provider-action-form" onSubmit={preview}><label>Local event<select value={eventId} onChange={event=>{setEventId(event.target.value);setProposal(null);}}><option value="">Choose event</option>{events.map(item=><option key={item.id} value={item.id}>{item.title}</option>)}</select></label><label>Provider connection<select value={connectionId} onChange={event=>{setConnectionId(event.target.value);setProposal(null);}}><option value="">Choose connection</option>{connections.map(item=><option key={item.id} value={item.id}>{item.label} · {item.state.replaceAll("_"," ")}</option>)}</select></label><label>Action<select value={kind} onChange={event=>{setKind(event.target.value as typeof kind);setProposal(null);}}>{["create","update","delete","respond"].map(value=><option key={value}>{value}</option>)}</select></label><label>Provider calendar ID<input value={targetCalendarId} onChange={event=>{setTargetCalendarId(event.target.value);setProposal(null);}} placeholder="Exact selected calendar ID"/></label><label>Recipients, comma-separated<input value={recipients} onChange={event=>{setRecipients(event.target.value);setProposal(null);}} placeholder="Optional; invitations require review"/></label>{kind==="respond"&&<label>Response<select value={response} onChange={event=>setResponse(event.target.value as typeof response)}><option value="accepted">Accepted</option><option value="tentative">Tentative</option><option value="declined">Declined</option></select></label>}<button className="primary" disabled={!eventId||!connectionId||!targetCalendarId.trim()}>Preview exact action</button></form>{!connections.length&&<p className="quiet-empty">No Microsoft or Google calendar connection is registered. Registering one does not make it live.</p>}{proposal?.kind==="provider_calendar_action"&&<div className="provider-action-preview"><strong>{proposal.diff.actionKind} · {selectedEvent?.title}</strong><span>Connection: {selectedConnection?.label??proposal.diff.connectionId} · target: {proposal.diff.targetCalendarId}</span><span>Recipients: {proposal.diff.recipients.map(item=>item.address).join(", ")||"none"}</span><span>Public fields: {proposal.diff.publicFields.title} · {friendlyDate(proposal.diff.publicFields.startsAt)} to {friendlyDate(proposal.diff.publicFields.endsAt)}</span><small>Excluded: {proposal.diff.privateFieldsExcluded.join(", ")}</small><small>{proposal.stale?"Preview is stale; create a new one.":`Revision ${proposal.revision} · expires ${proposal.expiresAt?friendlyDate(proposal.expiresAt):"not set"}`}</small><div className="session-actions"><button className="primary" disabled={proposal.stale} onClick={()=>void accept()}>Queue reviewed action</button><button className="text-button danger" onClick={()=>setProposal(null)}>Discard preview</button></div></div>}<div className="settings-list">{actions.map(action=><article key={action.id}><div><strong>{action.actionKind} · {action.state.replaceAll("_"," ")}</strong><small>{action.provider.replaceAll("_"," ")} · target {action.targetCalendarId} · {action.recipients.length} recipient(s)</small><small>{action.providerOperationId?`Provider operation ${action.providerOperationId}`:"No provider acknowledgement"} · attempts {action.attemptCount}{action.sendsDisabledAfterRestore?" · sends disabled after restore":""}</small></div>{action.state==="pending"&&<button className="text-button danger" onClick={()=>void cancel(action)}>Cancel unsent</button>}</article>)}{!actions.length&&<p className="quiet-empty">No provider actions. Local calendar changes remain local.</p>}</div></section>;
}

function CalendarView({ events, people, createEvent }: { events: CalendarEvent[]; people: CalendarEntity[]; createEvent: (input:LocalEventInput) => Promise<void> }) {
  const [title, setTitle] = useState("");
  const [personId, setPersonId] = useState("");
  const [repeatWeekly, setRepeatWeekly] = useState(false);
  const [conflicts, setConflicts] = useState<Array<{ id: string; startsAt: string; endsAt: string; titles: [string, string] }>>([]);
  const [context, setContext] = useState<{ eventId: string; items: PrepItem[] } | null>(null);
  const [prepText, setPrepText] = useState("");
  async function refreshConflicts() { const from = new Date(); const to = new Date(from.getTime() + 90 * 86400000); setConflicts((await api.calendarConflicts(from.toISOString(), to.toISOString())).items); }
  useEffect(() => { void refreshConflicts().catch(() => undefined); }, [events.length]);
  async function add(event: FormEvent) { event.preventDefault(); if (!title.trim()) return; const start = new Date(); start.setHours(start.getHours() + 1, 0, 0, 0); const end = new Date(start.getTime() + 60 * 60 * 1000); const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC"; await createEvent({ title, startsAt: start.toISOString(), endsAt: end.toISOString(), timezone, recurrence: repeatWeekly ? { frequency: "weekly", interval: 1, timezone, count: 12 } : undefined, entityIds: personId ? [personId] : [] }); setTitle(""); setPersonId(""); setRepeatWeekly(false); }
  async function openContext(eventId: string) { const result = await api.privateEventContext(eventId); setContext({ eventId, items: result.prepItems }); }
  async function addPrep(event: FormEvent, eventId: string) { event.preventDefault(); if (!prepText.trim()) return; await api.createPrepItem(eventId, prepText.trim()); setPrepText(""); await openContext(eventId); }
  async function togglePrep(item: PrepItem) { await api.updatePrepItem(item.eventId, item, item.status === "packed" ? "needed" : "packed"); await openContext(item.eventId); }
  return <><PageTitle eyebrow="Your time" title="Calendar" copy="Fixed commitments and flexible work, without leaking private preparation."/><form className="event-form" onSubmit={add}><input value={title} onChange={event => setTitle(event.target.value)} placeholder="Quick event one hour from now…"/><select value={personId} onChange={event => setPersonId(event.target.value)}><option value="">No participant</option>{people.map(person => <option key={person.id} value={person.id}>{person.name}</option>)}</select><label className="repeat-toggle"><input type="checkbox" checked={repeatWeekly} onChange={event => setRepeatWeekly(event.target.checked)}/> Weekly × 12</label><button className="primary" disabled={!title.trim()}><Plus size={18}/> Add</button></form>{conflicts.length > 0 && <div className="conflict-banner"><strong>{conflicts.length} calendar conflict{conflicts.length === 1 ? "" : "s"} in the next 90 days</strong>{conflicts.slice(0, 3).map(item => <span key={item.id}>{item.titles.join(" overlaps ")} · {friendlyDate(item.startsAt)}</span>)}</div>}<div className="calendar-list">{events.map(item => <article key={item.id} className="calendar-event"><time><strong>{new Date(item.startsAt).getDate()}</strong><span>{new Intl.DateTimeFormat(undefined, { month: "short" }).format(new Date(item.startsAt))}</span></time><div><h3>{item.title}</h3><p>{friendlyDate(item.startsAt)} – {new Intl.DateTimeFormat(undefined, { hour: "2-digit", minute: "2-digit" }).format(new Date(item.endsAt))}{item.recurrence ? ` · ${item.recurrence.frequency} recurrence` : ""}</p>{context?.eventId === item.id && <div className="private-prep"><span>Private preparation</span>{context.items.length ? context.items.map(prep => <button className={prep.status === "packed" ? "prep-row packed" : "prep-row"} key={prep.id} onClick={() => void togglePrep(prep)}>{prep.status === "packed" ? <CheckCircle2 size={16}/> : <Circle size={16}/>}<span>{prep.text}</span></button>) : <p>No linked preparation.</p>}<form className="prep-form" onSubmit={event => void addPrep(event, item.id)}><input value={prepText} onChange={event => setPrepText(event.target.value)} placeholder="Add private preparation…"/><button disabled={!prepText.trim()}>Add</button></form><small>Packing an item does not fulfill its underlying promise.</small></div>}</div><button className="text-button context-button" onClick={() => void openContext(item.id)}>Private context</button></article>)}{events.length === 0 && <div className="large-empty"><CalendarDays/><h2>Your calendar is open</h2><p>Add a local event. Nothing is sent to another person or provider.</p></div>}</div></>;
}

function SearchWorkspace({ onOpen }: { onOpen: (item: Pick<SearchItem, "kind" | "id">) => void }) {
  const [tab, setTab] = useState<"ask" | "find">("ask");
  return <><div className="knowledge-tabs"><button className={tab === "ask" ? "active" : ""} onClick={() => setTab("ask")}><MessageSquare size={17}/> Ask</button><button className={tab === "find" ? "active" : ""} onClick={() => setTab("find")}><Search size={17}/> Find</button></div>{tab === "ask" ? <AskWorkspace onOpen={onOpen}/> : <FindWorkspace onOpen={onOpen}/>}</>;
}

function AskWorkspace({ onOpen }: { onOpen: (item: Pick<SearchItem, "kind" | "id">) => void }) {
  const [chat, setChat] = useState<Chat | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [question, setQuestion] = useState("");
  const [mode, setMode] = useState<"grounded" | "brainstorm">("grounded");
  const [job, setJob] = useState<JobHandle | Job | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => { void api.chats().then(async result => { const first = result.items[0] ?? null; setChat(first); if (first) setMessages((await api.chatMessages(first.id)).items); }).catch(() => setError("Chats are unavailable while the home host is offline.")); }, []);

  async function submit(event: FormEvent) {
    event.preventDefault(); if (!question.trim()) return;
    setBusy(true); setError(null);
    try {
      const activeChat = chat ?? await api.createChat(mode === "brainstorm" ? "brainstorm" : "notes");
      if (!chat) setChat(activeChat);
      const accepted = await api.ask(activeChat.id, question.trim(), mode);
      const [savedMessages,savedJob]=await Promise.all([api.chatMessages(activeChat.id),api.job(accepted.jobId)]);
      setMessages(savedMessages.items);
      setJob(savedJob); setQuestion("");
    } catch { setError("The question was not saved. Keep it here and try again."); }
    finally { setBusy(false); }
  }

  async function refreshAnswer() {
    if (!job || !chat) return;
    try {
      const next = await api.job(job.id); setJob(next);
      setMessages((await api.chatMessages(chat.id)).items);
      if (["succeeded", "failed", "cancelled", "superseded"].includes(next.status)) setJob(null);
    } catch { setError("Could not refresh the saved answer job."); }
  }

  useEffect(() => { if (!job || ["succeeded", "failed", "cancelled", "superseded"].includes(job.status)) return; const timer = window.setInterval(() => void refreshAnswer(), 2_000); return () => window.clearInterval(timer); }, [job?.id, job?.status, chat?.id]);

  return <><PageTitle eyebrow="Source-grounded workspace" title="Ask" copy="Grounded answers can cite only authorized passages selected by your home host. Brainstorming is clearly marked and never pretends to use sources."/>
    <div className="ask-thread">{messages.length === 0 && <div className="ask-empty"><MessageSquare/><h2>Ask your saved knowledge</h2><p>Grounded mode waits for the local worker and preserves exact note citations.</p></div>}{messages.map(message => <article key={message.id} className={`chat-message ${message.role}`}><div className="message-label"><span>{message.role === "user" ? "You" : message.mode === "brainstorm" ? "Sorta · brainstorm" : "Sorta · grounded"}</span><small>{message.status.replaceAll("_", " ")}</small></div>{message.text ? <p>{message.text}</p> : <p className="waiting-copy">Saved. Waiting for the approved local worker…</p>}{message.citations.length > 0 && <div className="citations">{message.citations.map(citation => <button key={citation.citationId} onClick={() => onOpen({ kind: "note", id: citation.noteId })}><strong>[{citation.citationId}] {citation.title}</strong><span>“{citation.quote}”</span><small>Revision {citation.revision} · characters {citation.startOffset}–{citation.endOffset}</small></button>)}</div>}</article>)}</div>
    <form className="ask-composer" onSubmit={submit}><textarea autoFocus value={question} onChange={event => setQuestion(event.target.value)} placeholder="Ask about your saved notes…"/><div><select value={mode} onChange={event => setMode(event.target.value as typeof mode)} aria-label="Answer mode"><option value="grounded">Grounded · citations required</option><option value="brainstorm">Brainstorm · no sources</option></select><span>{mode === "grounded" ? "Private retrieval stays on the home host." : "Ideas will be labeled as ungrounded."}</span><button className="primary" disabled={busy || !question.trim()}>{busy ? "Saving…" : "Ask"}</button></div></form>{error && <p className="form-error">{error}</p>}{job && <div className="job-card compact-job"><div className="job-icon"><Zap/></div><div><p className="eyebrow">Durable answer job</p><h2>{job.status.replaceAll("_", " ")}</h2><p>Your question is saved. No answer is invented while the local models are unavailable.</p></div><div className="job-actions"><button className="text-button" onClick={() => void refreshAnswer()}>Refresh</button><button className="text-button danger" onClick={async () => { await api.cancelJob(job.id); await refreshAnswer(); }}>Cancel</button></div></div>}</>;
}

function FindWorkspace({ onOpen }: { onOpen: (item: Pick<SearchItem, "kind" | "id">) => void }) {
  const [cacheNotice, setCacheNotice] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [mode, setMode] = useState<"lexical" | "hybrid" | "semantic">("lexical");
  const [result, setResult] = useState<SearchResult | null>(null);
  const [job, setJob] = useState<JobHandle | Job | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [aiStatus, setAiStatus] = useState<AiStatus | null>(null);
  const [profiles, setProfiles] = useState<ModelProfile[]>([]);

  useEffect(() => {
    void Promise.all([api.aiStatus(), api.modelProfiles()])
      .then(([status, modelProfiles]) => { setAiStatus(status); setProfiles(modelProfiles.items); })
      .catch(() => setAiStatus(null));
  }, []);

  async function run(event: FormEvent) {
    event.preventDefault(); if (!query.trim()) return;
    setBusy(true); setError(null); setResult(null); setJob(null); setCacheNotice(null);
    try {
      const {response,cachedAt} = await searchWithOfflineFallback(query.trim(), mode);
      if(cachedAt)setCacheNotice(`Offline keyword search · cached notes, task titles and calendar titles only, from ${friendlyDate(cachedAt)}. Saved local note edits are included; revision numbers are the cached server baseline. Uncached records and AI search are unavailable.`);
      if ("items" in response) setResult(response);
      else setJob(response);
    } catch { setError("Search could not run. Your query has not been sent anywhere else."); }
    finally { setBusy(false); }
  }

  async function refreshJob() {
    if (!job) return;
    try {
      const next = await api.job(job.id);
      if (next.result?.type === "search") { setResult(next.result.search); setJob(null); }
      else setJob(next);
    } catch { setError("Could not refresh this job."); }
  }

  useEffect(() => {
    if (!job || ["succeeded", "failed", "cancelled", "superseded"].includes(job.status)) return;
    const timer = window.setInterval(() => void refreshJob(), 2_000);
    return () => window.clearInterval(timer);
  }, [job?.id, job?.status]);

  async function cancelJob() {
    if (!job) return;
    try { setJob(await api.cancelJob(job.id)); } catch { setError("Could not cancel this job."); }
  }

  async function testModel(profileId: string) {
    setError(null);
    try {
      const worker = aiStatus?.workers.find((candidate) => candidate.state !== "worker_offline" && candidate.state !== "error");
      if (!worker) throw new Error("no_worker");
      setJob(await api.testAi(worker.id, profileId));
    }
    catch { setError("The model test could not be queued."); }
  }

  return <>{cacheNotice && <p className="success-banner" role="status">{cacheNotice}</p>}<PageTitle eyebrow="Authorized retrieval" title="Find" copy="Lexical search works without AI. Hybrid and semantic searches wait for the approved local worker."/><div className={`ai-status ${aiStatus?.state ?? "unknown"}`}><span className="status-dot"/><div><strong>Local AI: {aiStatus ? aiStatus.state.replaceAll("_", " ") : "status unavailable"}</strong><small>{aiStatus ? `${aiStatus.availableModels.length} runtime model${aiStatus.availableModels.length === 1 ? "" : "s"} · ${aiStatus.queuedJobs} queued job${aiStatus.queuedJobs === 1 ? "" : "s"} · cloud fallback off` : "Lexical search remains available."}</small></div>{profiles.map(profile => <button key={profile.id} className="model-chip" onClick={() => void testModel(profile.id)} title="Queue a real harmless capability test"><span>{profile.model}</span><small>{profile.backend.replaceAll("_", " ")} · {profile.installed ? profile.tested ? "tested" : "installed · untested" : "missing"}</small></button>)}</div><form className="search-form" onSubmit={run}><div className="search-input"><Search size={20}/><input autoFocus value={query} onChange={event => setQuery(event.target.value)} placeholder="Search notes, tasks, and calendar…"/></div><select value={mode} onChange={event => setMode(event.target.value as typeof mode)} aria-label="Search mode"><option value="lexical">Lexical · available offline</option><option value="hybrid">Hybrid · local model</option><option value="semantic">Semantic · local model</option></select><button className="primary" disabled={busy || !query.trim()}>{busy ? "Searching…" : "Search"}</button></form>{error && <p className="form-error">{error}</p>}{result && <div className="search-summary"><span>{result.items.length} results</span><span>Coverage: {result.coverage.kinds.join(", ")}</span><span>{result.coverage.semanticAvailable ? "Semantic index available" : "Lexical coverage only"}</span></div>}{result && <div className="search-results">{result.items.map(item => <button key={`${item.kind}-${item.id}`} onClick={() => onOpen(item)}><span className={`result-kind ${item.kind}`}>{item.kind.replace("_", " ")}</span><div><h3>{item.title}</h3><p>{item.excerpt}</p><small>Revision {item.revision} · score {item.score.toFixed(3)}</small></div></button>)}{result.items.length === 0 && <div className="large-empty"><Search/><h2>No lexical matches</h2><p>Try words that appear in the original note, task, or event.</p></div>}</div>}{job && <div className="job-card"><div className="job-icon"><Zap/></div><div><p className="eyebrow">Durable job</p><h2>{job.kind.replaceAll("_", " ")}</h2><p>Status: <strong>{job.status.replaceAll("_", " ")}</strong>{"stage" in job ? ` · ${job.stage.replaceAll("_", " ")}` : ""}</p><p>The request is saved, but no result is invented while the local worker is unavailable.</p></div><div className="job-actions"><button className="text-button" onClick={() => void refreshJob()}>Refresh</button>{!["succeeded", "failed", "cancelled", "superseded"].includes(job.status) && <button className="text-button danger" onClick={() => void cancelJob()}>Cancel</button>}</div></div>}</>;
}
